  /* 209 AG · ESEN-CAND-02: listas de claves precomputadas UNA sola vez (no en cada phraseReplace). */
  function ordenarClaves(map){ return Object.keys(map).filter(function(k){ return k.length>=4 && k.length<=90; }).sort(function(a,b){return b.length-a.length;}); }
  var ES_EN_KEYS = ordenarClaves(ES_EN);
